@startuml

class Boeing {
  + Name : string
}

class Employee {
  + Name : string
}

class Salesperson extends Employee {}

class Airline {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

class Airplane {
  + Model : string
}

Boeing "1" -- "*" Contract : manages
Boeing "1" -- "*" Airplane : builds
Contract "1" -- "1..*" Acquisition : consists of
Acquisition "1" -- "1" Airplane : includes
Acquisition "0..*" -- "1" Airline : for
Contract "0..*" -- "1" Salesperson : is managed by
Contract "0..*" -- "1" Airline : is with
Airline "0..1" -- "0..1" Airline : mother-daughter relationship

@enduml

